-- =====================================================================
-- SportFamilyRD - Datos de ejemplo (PostgreSQL)
-- =====================================================================
-- Requiere que database/schema.sql se haya ejecutado antes.
--
--   psql -d sportfamilyrd -f database/schema.sql
--   psql -d sportfamilyrd -f database/seed.sql
--
-- AVISO DE PRIVACIDAD
-- Este archivo contiene solo datos de catalogo (deportes y productos) y
-- usuarios inventados. No incluye usuarios reales, contraseñas, tokens de
-- acceso, mensajes ni publicaciones de la base de datos de produccion.
-- =====================================================================

BEGIN;

-- ---------------------------------------------------------------------
-- Usuarios de demostracion
-- La contraseña de los tres es: password
-- Cambiala antes de exponer este entorno en cualquier red.
-- ---------------------------------------------------------------------
ON CONFLICT (id) DO NOTHING;

-- ---------------------------------------------------------------------
-- Catalogo de deportes (directorio)
-- ---------------------------------------------------------------------
ON CONFLICT (id) DO NOTHING;

-- ---------------------------------------------------------------------
-- Catalogo de productos (tienda)
-- ---------------------------------------------------------------------
ON CONFLICT (id) DO NOTHING;

-- ---------------------------------------------------------------------
-- Resincronizar las secuencias
-- Al insertar ids explicitos la secuencia no avanza. Sin este paso, el
-- primer registro que cree la aplicacion chocaria con un id existente.
-- ---------------------------------------------------------------------
SELECT setval(pg_get_serial_sequence('users', 'id'), COALESCE((SELECT MAX(id) FROM "users"), 1));
SELECT setval(pg_get_serial_sequence('sports', 'id'), COALESCE((SELECT MAX(id) FROM "sports"), 1));
SELECT setval(pg_get_serial_sequence('products', 'id'), COALESCE((SELECT MAX(id) FROM "products"), 1));

COMMIT;
